mapper.update:
UPDATE identity_discord_oauth_attempt SET encrypted_refresh_token=#{encryptedToken},updated_at=UTC_TIMESTAMP(6)
  WHERE user_id=#{userId} AND request_id=#{requestId} AND code_digest=#{codeDigest}
  AND attempt_status='EXCHANGING' AND encrypted_refresh_token IS NULL

UPDATE identity_discord_oauth_attempt SET attempt_status=#{status},failure_code=#{failureCode},
  encrypted_state=NULL,encrypted_verifier=NULL,updated_at=UTC_TIMESTAMP(6)
  WHERE user_id=#{userId} AND request_id=#{requestId} AND attempt_status=#{expected}

UPDATE identity_discord_oauth_attempt SET attempt_status='BOUND',encrypted_refresh_token=NULL,
  updated_at=UTC_TIMESTAMP(6) WHERE user_id=#{userId} AND request_id=#{requestId}
  AND generation=#{generation} AND attempt_status='VERIFIED'
